import path from 'node:path';
import { mkdirSync, readFileSync } from 'node:fs';
import { sql } from 'drizzle-orm';
import type { PgDatabase, PgQueryResultHKT } from 'drizzle-orm/pg-core';
import { DATA_DIR } from '../config.ts';
import { appRoleName, canManageSchema, ensureAppRole, type Query } from './roles.ts';
import * as schema from './schema.ts';

export type Database = PgDatabase<PgQueryResultHKT, typeof schema>;

// SQL migrations generated by drizzle-kit, bundled at build time.
const MIGRATIONS = import.meta.glob('../../../../drizzle/*.sql', { query: '?raw', import: 'default', eager: true }) as Record<
	string,
	string
>;

/**
 * Remote connections always use verified TLS (CA from DATABASE_CA_FILE for hosted providers). Only a
 * local database may skip it.
 */
/** Parses DATABASE_URL with readable errors. Never prints the URL (contains the password). */
function databaseHost(url: string): string {
	let parsed: URL;
	try {
		parsed = new URL(url.trim());
	} catch {
		throw new Error(
			'DATABASE_URL is not a valid address. It should look like postgresql://USER:PASSWORD@HOST:5432/postgres, on one line, ' +
				'without spaces. If the password contains @ # / : ? % or a space, write them as %40 %23 %2F %3A %3F %25 %20 ' +
				'(a # without quotes also starts a comment in the .env file). A DATABASE_URL set in the system environment ' +
				'takes precedence over the .env file.'
		);
	}
	if (!/^postgres(ql)?:$/.test(parsed.protocol)) throw new Error('DATABASE_URL must start with postgresql://');
	return parsed.hostname;
}

function tls(url: string): false | { ca?: string; rejectUnauthorized: true } {
	const host = databaseHost(url);
	if (['localhost', '127.0.0.1', '::1', '[::1]'].includes(host)) return false;
	const caFile = process.env.DATABASE_CA_FILE?.trim();
	if (!caFile) return { rejectUnauthorized: true };
	try {
		return { ca: readFileSync(caFile, 'utf8'), rejectUnauthorized: true };
	} catch {
		throw new Error(`DATABASE_CA_FILE points to a file that cannot be read: ${caFile}`);
	}
}

/** Rows of a raw query, for the role set-up (lib/server/db/roles.ts). */
type Rows = { rows: Record<string, unknown>[] };

/**
 * Connects and serves every request as the restricted role (DATABASE_APP_ROLE, default `sqwer_app`, roles.ts):
 * 1. Migrations run on a short-lived owner connection (MIGRATION_DATABASE_URL, or DATABASE_URL when it is
 *    the owner); the role is created and granted row access.
 * 2. Requests use DATABASE_URL, switching to the role per connection when it is the owner.
 * The switch is verified before the first request; on failure the database isn't used.
 */
async function connect(): Promise<Database> {
	const url = process.env.DATABASE_URL?.trim();
	const role = appRoleName();
	const manual = process.env.DATABASE_MIGRATIONS === 'manual';
	if (url) {
		const { default: pg } = await import('pg');
		const { drizzle } = await import('drizzle-orm/node-postgres');

		// 1. Migrations and the role, with the owner credentials.
		const ownerUrl = process.env.MIGRATION_DATABASE_URL?.trim() || url;
		const owner = new pg.Client({ connectionString: ownerUrl, ssl: tls(ownerUrl), application_name: 'sqwer-migrate', connectionTimeoutMillis: 10_000 });
		await owner.connect();
		try {
			await migrate(drizzle(owner, { schema }) as unknown as Database);
			const query: Query = async (text, params = []) => ((await owner.query(text, params)) as Rows).rows;
			if (role && !manual && (await canManageSchema(query))) await ensureAppRole(query, role);
		} finally {
			await owner.end().catch(() => {});
		}

		// 2. Requests, as the restricted role: switch to it unless DATABASE_URL already is it.
		let switchTo: string | null = null;
		if (role) {
			const probe = new pg.Client({ connectionString: url, ssl: tls(url), connectionTimeoutMillis: 10_000 });
			await probe.connect();
			try {
				const [me] = ((await probe.query('SELECT current_user AS name')) as Rows).rows;
				if (me?.name !== role) switchTo = role;
			} finally {
				await probe.end().catch(() => {});
			}
		}
		return connectPool(pg, drizzle, url, switchTo, role);
	}
	// No server configured: an embedded PostgreSQL stored on disk, with the same restricted role.
	const { PGlite } = await import('@electric-sql/pglite');
	const { drizzle } = await import('drizzle-orm/pglite');
	const dir = path.join(DATA_DIR, 'pglite');
	mkdirSync(dir, { recursive: true });
	const pglite = new PGlite(dir);
	const d = drizzle(pglite, { schema }) as unknown as Database;
	await migrate(d);
	if (role) {
		await ensureAppRole(async (text, params = []) => (await pglite.query<Record<string, unknown>>(text, params)).rows, role);
		await pglite.exec(`SET ROLE "${role}"`);
		await assertRole((text) => pglite.query<Record<string, unknown>>(text).then((r) => r.rows), role);
	}
	return d;
}

/** The request pool: every connection switches to `switchTo` first, and the role is checked before use. */
async function connectPool(
	pg: typeof import('pg').default,
	drizzle: typeof import('drizzle-orm/node-postgres').drizzle,
	url: string,
	switchTo: string | null,
	role: string | null
): Promise<Database> {
	const pool = new pg.Pool({
		connectionString: url,
		max: Number(process.env.DATABASE_POOL_SIZE ?? 5),
		ssl: tls(url),
		application_name: 'sqwer',
		// Ends slow queries, connects and idle transactions so the small pool can't be starved.
		connectionTimeoutMillis: 10_000,
		statement_timeout: Number(process.env.DATABASE_STATEMENT_TIMEOUT_MS ?? 15_000),
		idle_in_transaction_session_timeout: 30_000,
		// Each new connection switches to the restricted role first; on failure it is closed.
		...(switchTo ? { onConnect: async (client: import('pg').ClientBase) => void (await client.query(`SET ROLE "${switchTo}"`)) } : {})
	});
	// An idle connection that the server drops must not crash the process.
	pool.on('error', (e) => console.error(JSON.stringify({ kind: 'database', error: String(e?.message ?? e).slice(0, 200) })));
	if (role) await assertRole(async (text) => ((await pool.query(text)) as Rows).rows, role);
	return drizzle(pool, { schema }) as unknown as Database;
}

/** Refuses to serve requests unless they run as the restricted role. */
async function assertRole(query: (text: string) => Promise<Record<string, unknown>[]>, role: string) {
	const [me] = await query('SELECT current_user AS name');
	if (me?.name !== role) {
		throw new Error(
			`Requests would not run as the restricted database role "${role}" (they run as "${String(me?.name)}"). ` +
				'Check that the role exists and that the DATABASE_URL user may switch to it, or set DATABASE_APP_ROLE=none.'
		);
	}
}

/**
 * Applies pending migrations. The check is read-only, so a row-only role starts fine when up to date;
 * changes need the owner role (`npm run db:migrate`).
 */
export async function migrate(db: Database) {
	const rows = (r: unknown) => (r as { rows: Record<string, unknown>[] }).rows;
	const [exists] = rows(await db.execute(sql`SELECT to_regclass('public.sqwer_migrations') IS NOT NULL AS present`));
	const done = new Set<string>();
	if (exists?.present) {
		for (const r of rows(await db.execute(sql`SELECT name FROM sqwer_migrations`))) done.add(String(r.name));
	}
	const pending = Object.keys(MIGRATIONS)
		.sort()
		.filter((file) => !done.has(file.split('/').pop()!));
	if (!pending.length) return;
	if (process.env.DATABASE_MIGRATIONS === 'manual') {
		throw new Error(
			`The database schema is out of date (${pending.length} pending migration${pending.length === 1 ? '' : 's'}). ` +
				'Run `npm run db:migrate -w web` with the owner role (MIGRATION_DATABASE_URL), then restart.'
		);
	}
	if (!exists?.present) {
		await db.execute(
			sql`CREATE TABLE IF NOT EXISTS sqwer_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())`
		);
		await db.execute(sql`ALTER TABLE sqwer_migrations ENABLE ROW LEVEL SECURITY`);
	}

	for (const file of pending) {
		const name = file.split('/').pop()!;
		const statements = MIGRATIONS[file]!.split('--> statement-breakpoint')
			.map((s) => s.trim())
			.filter(Boolean);
		await db.transaction(async (tx) => {
			for (const statement of statements) await tx.execute(sql.raw(statement));
			await tx.execute(sql`INSERT INTO sqwer_migrations (name) VALUES (${name})`);
		});
	}
}

let ready: Promise<Database> | null = null;
let lastFailure = '';

/** The database, migrated and connected as the restricted role on first use. */
export function db(): Promise<Database> {
	ready ??= connect()
		.catch((e) => {
			// Retry on the next request instead of failing every request until a restart.
			ready = null;
			// The reason is logged once per distinct message (never the connection string).
			const reason = String((e as Error)?.message ?? e).slice(0, 300);
			if (reason !== lastFailure) {
				lastFailure = reason;
				console.error(JSON.stringify({ kind: 'database', error: reason }));
			}
			const host = process.env.DATABASE_URL ? new URL(process.env.DATABASE_URL).hostname : '';
			if (/ENOTFOUND/.test(String(e?.cause ?? e)) && /^db\..+\.supabase\.co$/.test(host)) {
				// Supabase's direct host has only an IPv6 address; networks without IPv6 cannot reach it.
				console.error(
					`Cannot resolve ${host}: Supabase's direct connection needs IPv6. Use the session pooler instead ` +
						'(Supabase dashboard: Connect, then Session pooler), for example ' +
						'postgresql://postgres.<project-ref>:<password>@aws-0-<region>.pooler.supabase.com:5432/postgres'
				);
			}
			throw e;
		});
	return ready;
}

export { schema };
